function tribonacci(n) {
  if (n === 0) return 0;
  if (n === 1 || n === 2) return 1;
  let a = 0;
  let b = 1;
  let c = 1;
  for (let i = 3; i <= n; i++) {
    const next = a + b + c;
    a = b;
    b = c;
    c = next;
  }
  return c;
}

