function minCoinsTopDown(coins, amount) {
  const memo = {};

  function best(rest) {
    if (rest === 0) return 0;
    if (rest in memo) return memo[rest];
    let found = Infinity;
    for (const c of coins) {
      if (c <= rest) {
        const sub = best(rest - c);
        if (sub + 1 < found) found = sub + 1;
      }
    }
    memo[rest] = found;
    return found;
  }

  const answer = best(amount);
  return answer === Infinity ? -1 : answer;
}

