function minCoins(coins, amount) {
  if (amount in cache) return cache[amount];
  if (amount === 0) return 0;
  let best = Infinity;
  for (const c of coins) {
    if (c <= amount) {
      const rest = minCoins(coins, amount - c);
      if (rest !== -1 && rest + 1 < best) best = rest + 1;
    }
  }
  const result = best === Infinity ? -1 : best;
  cache[amount] = result;
  return result;
}

function solve(coinSets, amount) {
  return coinSets.map((coins) => minCoins(coins, amount));
}

