function minCoins(coins, amount) {
  const cache = {};

  function go(rest) {
    if (rest === 0) return 0;
    if (rest in cache) return cache[rest];
    let best = Infinity;
    for (const c of coins) {
      if (c <= rest) {
        const sub = go(rest - c);
        if (sub + 1 < best) best = sub + 1;
      }
    }
    cache[rest] = best;
    return best;
  }

  const answer = go(amount);
  return answer === Infinity ? -1 : answer;
}

function solve(coinSets, amount) {
  return coinSets.map((coins) => minCoins(coins, amount));
}
